package com.jdte.common.blockentities;

import com.jdte.common.manager.EntityAccelerationManager;
import com.jdte.common.upgrades.*;
import com.jdte.setup.*;
import com.direwolf20.justdirethings.setup.Config;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Cow;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.fluids.FluidStack;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import net.minecraftforge.gametest.*;

@GameTestHolder("jdte") @PrefixGameTestTemplate(false)
public final class EntityAcceleratorGameTests {
 private static final BlockPos POS=new BlockPos(2,1,2),TARGET=new BlockPos(4,1,2);
 private static AdvancedEntityAcceleratorBE place(GameTestHelper h,boolean extended){h.setBlock(POS,extended?JDTEBlocks.EXTENDED_ENTITY_ACCELERATOR.get():JDTEBlocks.ADVANCED_ENTITY_ACCELERATOR.get());var p=h.absolutePos(POS);var s=h.getLevel().getBlockState(p);var be=extended?new ExtendedEntityAcceleratorBE(p,s){@Override public AABB getAABB(BlockPos p){return new AABB(h.absolutePos(TARGET)).inflate(.5);}}:new AdvancedEntityAcceleratorBE(p,s){@Override public AABB getAABB(BlockPos p){return new AABB(h.absolutePos(TARGET)).inflate(.5);}};h.getLevel().setBlockEntity(be);be.getEnergyStorage().setEnergy(be.getMaxEnergy());be.getFluidTank().setFluid(new FluidStack(com.direwolf20.justdirethings.setup.Registration.TIME_FLUID_SOURCE.get(),1000));return be;}
 private static Cow cow(GameTestHelper h){var c=h.spawn(EntityType.COW,TARGET);c.setAge(-10000);c.setPersistenceRequired();return c;}
 private static void card(AdvancedEntityAcceleratorBE be,Item item,int slot){if(!UpgradeHelper.getUpgradeHandler(be).insertItem(slot,new ItemStack(item),false).isEmpty())throw new IllegalStateException("Rejected accelerator card "+item);}
 private static int rf(int work){return TimeAcceleratorCostMath.energyCost(work,Config.TIME_WAND_FE_COST.get());}
 @GameTest(template="mineral_empty") public static void realAgeAndExactSourceCosts(GameTestHelper h){for(boolean extended:new boolean[]{false,true}){var be=place(h,extended);var c=cow(h);var before=c.position();c.setDeltaMovement(new Vec3(.2,0,.2));int energy=be.getEnergyStorage().getEnergyStored();double fluid=TimeAcceleratorCostMath.fluidCost(3,Config.TIME_WAND_FLUID_COST.get(),JDTEConfig.COMMON.entityAccelerator.fluidCostMultiplier.get(),extended?5:2);be.accelerateEntities();h.assertTrue(c.getAge()==-9997&&c.position().equals(before),"real age advances three; travel/AI suppressed during sub-ticks");h.assertTrue(be.getEnergyStorage().getEnergyStored()==energy-rf(3)&&Math.abs(be.getPendingFluidCost()-(fluid-Math.floor(fluid)))<1e-9&&be.getFluidTank().getFluidAmount()==1000-(int)Math.floor(fluid),"exact tier FE/fractional time-fluid cost");h.assertTrue(!EntityAccelerationManager.isSuppressingAi(),"thread scope cleared");c.discard();}h.succeed();}
 @GameTest(template="mineral_empty") public static void noWorkNoChargeAndInsufficientAtomicity(GameTestHelper h){var be=place(h,false);var start=be.saveWithFullMetadata();be.accelerateEntities();h.assertTrue(start.equals(be.saveWithFullMetadata()),"no target no cost");var c=cow(h);be.setMultiplier(1);int before=be.getEnergyStorage().getEnergyStored();be.accelerateEntities();h.assertTrue(c.getAge()==-10000&&be.getEnergyStorage().getEnergyStored()==before,"one multiplier no work");be.setMultiplier(64);be.getEnergyStorage().setEnergy(0);int fluid=be.getFluidTank().getFluidAmount();be.accelerateEntities();h.assertTrue(c.getAge()==-10000&&be.getFluidTank().getFluidAmount()==fluid&&be.getPendingFluidCost()==0,"insufficient FE never pre-spends fluid or work");be.getEnergyStorage().setEnergy(be.getMaxEnergy());be.getFluidTank().setFluid(FluidStack.EMPTY);be.accelerateEntities();h.assertTrue(c.getAge()==-10000&&be.getEnergyStorage().getEnergyStored()==be.getMaxEnergy(),"insufficient fluid never pre-spends FE");h.succeed();}
 @GameTest(template="mineral_empty") public static void shortDebitRollsBackBothBuffers(GameTestHelper h){var be=place(h,false);var c=cow(h);int energy=be.getEnergyStorage().getEnergyStored();var fluid=be.getFluidTank().getFluid().copy();((com.jdte.mixin.EnergyStorageAccessor)be.getEnergyStorage()).jdte$setMaxExtract(1);be.accelerateEntities();h.assertTrue(c.getAge()==-10000&&be.getEnergyStorage().getEnergyStored()==energy&&be.getFluidTank().getFluid().isFluidStackIdentical(fluid)&&be.getPendingFluidCost()==0,"short real extraction rolls back FE/fluid/fraction and performs no ticks");h.succeed();}
 @GameTest(template="mineral_empty") public static void actualTierTargetBounds(GameTestHelper h){for(boolean extended:new boolean[]{false,true}){var be=place(h,extended);card(be,JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get(),0);be.getEnergyStorage().setEnergy(be.getMaxEnergy());be.setMultiplier(2);var cows=new java.util.ArrayList<Cow>();int limit=extended?64:32;for(int i=0;i<limit+1;i++)cows.add(cow(h));int energy=be.getEnergyStorage().getEnergyStored();be.accelerateEntities();h.assertTrue(cows.stream().filter(c->c.getAge()==-9999).count()==limit&&cows.stream().filter(c->c.getAge()==-10000).count()==1,"real source entity cap "+limit);h.assertTrue(be.getEnergyStorage().getEnergyStored()==energy-rf(limit),"pay only selected work");cows.forEach(Entity::discard);}h.succeed();}
 @GameTest(template="mineral_empty") public static void filtersAndInvalidEntities(GameTestHelper h){var be=place(h,false);var c=cow(h);be.getFilterHandler().setStackInSlot(0,new ItemStack(Items.SHEEP_SPAWN_EGG));be.getFilterData().allowlist=true;h.assertTrue(!be.isValidTargetEntity(c),"source allowlist excludes cow");be.getFilterHandler().setStackInSlot(0,new ItemStack(Items.COW_SPAWN_EGG));h.assertTrue(be.isValidTargetEntity(c),"changed egg invalidates cached fingerprint");be.getFilterData().allowlist=false;h.assertTrue(!be.isValidTargetEntity(c),"changed allowlist refreshes cache");h.assertTrue(!be.isValidTargetEntity(h.makeMockPlayer()),"players excluded");c.discard();h.assertTrue(!be.isValidTargetEntity(c),"removed entities excluded");h.succeed();}
 @GameTest(template="mineral_empty") public static void realUpgradeLimitsAndUltimateTicker(GameTestHelper h){var be=place(h,false);be.setMultiplier(Integer.MAX_VALUE);h.assertTrue(be.getMultiplier()==64,"Advanced upper bound");be.setMultiplier(Integer.MIN_VALUE);h.assertTrue(be.getMultiplier()==1,"lower bound");card(be,JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get(),0);card(be,JDTEItems.ULTIMATE_OVERCLOCK_UPGRADE.get(),1);be.getEnergyStorage().setEnergy(be.getMaxEnergy());h.assertTrue(be.getMaxEnergy()==10000000&&be.getMaxMB()==500000&&be.getEffectiveMultiplier()==128,"real Ultimate buffers/source multiplier");var c=cow(h);int energy=be.getEnergyStorage().getEnergyStored();var block=(com.jdte.common.blocks.AdvancedEntityAcceleratorBlock)be.getBlockState().getBlock();block.getTicker(h.getLevel(),be.getBlockState(),JDTEBlockEntities.ADVANCED_ENTITY_ACCELERATOR.get()).tick(h.getLevel(),be.getBlockPos(),be.getBlockState(),be);h.assertTrue(c.getAge()==-8730&&be.getEnergyStorage().getEnergyStored()==energy-rf(127)*10,"actual wrapper ten executions without external block-acceleration recursion");h.succeed();}
 @GameTest(template="mineral_empty") public static void guardedPortsPersistenceAndCapacityRemoval(GameTestHelper h){var be=place(h,false);card(be,JDTEItems.ULTIMATE_CAPACITY_UPGRADE.get(),0);be.getEnergyStorage().setEnergy(be.getMaxEnergy());be.getFluidTank().setFluid(new FluidStack(com.direwolf20.justdirethings.setup.Registration.TIME_FLUID_SOURCE.get(),10001));be.setMultiplier(17);var e=be.getCapability(ForgeCapabilities.ENERGY,Direction.UP).orElseThrow(IllegalStateException::new);var f=be.getCapability(ForgeCapabilities.FLUID_HANDLER,Direction.DOWN).orElseThrow(IllegalStateException::new);h.assertTrue(f.fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,100),FluidAction.EXECUTE)==0,"invalid foreign fluid rejected");h.assertTrue(UpgradeHelper.getUpgradeHandler(be).extractItem(0,1,false).isEmpty(),"cannot discard real stored capacity");var saved=be.saveWithFullMetadata();var replacement=new AdvancedEntityAcceleratorBE(be.getBlockPos(),be.getBlockState());be.setRemoved();h.getLevel().setBlockEntity(replacement);replacement.load(saved);h.assertTrue(e.receiveEnergy(100,false)==0&&e.extractEnergy(100,false)==0&&f.drain(100,FluidAction.EXECUTE).isEmpty(),"old interfaces invalid after replacement");h.assertTrue(replacement.getEnergyStorage().getEnergyStored()==10000000&&replacement.getFluidTank().getFluidAmount()==10001&&replacement.getMultiplier()==17&&UpgradeHelper.hasUltimateCapacity(replacement),"fresh NBT buffers/config/cards survive");replacement.onChunkUnloaded();h.assertTrue(EntityAccelerationManager.runAcceleratedTicks(cow(h),0)==0,"no requested work");h.succeed();}
 @GameTest(template="mineral_empty") public static void reentrancyRemovalAndExceptionScope(GameTestHelper h){var pos=h.absolutePos(TARGET);class RecursiveCow extends Cow {int calls;RecursiveCow(){super(EntityType.COW,h.getLevel());}public void tick(){calls++;h.assertTrue(EntityAccelerationManager.runAcceleratedTicks(this,4)==0,"nested tick request rejected");discard();}}var c=new RecursiveCow();c.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);h.getLevel().addFreshEntity(c);h.assertTrue(EntityAccelerationManager.runAcceleratedTicks(c,9)==1&&c.calls==1&&!EntityAccelerationManager.isSuppressingAi(),"removed target stops immediately with scope cleared");class ThrowingCow extends Cow{ThrowingCow(){super(EntityType.COW,h.getLevel());}public void tick(){throw new IllegalStateException("expected tick failure");}}var t=new ThrowingCow();t.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5);h.getLevel().addFreshEntity(t);boolean raised=false;try{EntityAccelerationManager.runAcceleratedTicks(t,4);}catch(IllegalStateException expected){raised=expected.getMessage().equals("expected tick failure");}h.assertTrue(raised&&!EntityAccelerationManager.isSuppressingAi(),"tick exception propagates without leaked AI scope");t.discard();h.succeed();}
}
